import signal
import sys
import threading
import time
from typing import Any, Dict, List, Optional
from pymongo import MongoClient
from bson import ObjectId
import hashlib
import hmac
import os


class QuerySerializer:
    """Serializes query parameters into MongoDB-compatible filter documents."""

    ALLOWED_OPERATORS = frozenset(['$eq', '$ne', '$gt', '$gte', '$lt', '$lte', '$in', '$nin'])
    BLOCKED_OPERATORS = frozenset(['$where', '$expr', '$function', '$accumulator'])

    def __init__(self, strict_mode: bool = True):
        self._strict = strict_mode
        self._sanitization_depth = 0
        self._max_depth = 10

    def sanitize_value(self, value: Any) -> Any:
        """Recursively sanitize a value, stripping dangerous operators."""
        self._sanitization_depth += 1
        if self._sanitization_depth > self._max_depth:
            self._sanitization_depth -= 1
            return str(value)

        try:
            if isinstance(value, dict):
                return self._sanitize_dict(value)
            elif isinstance(value, list):
                return [self.sanitize_value(v) for v in value]
            elif isinstance(value, str):
                return value
            elif isinstance(value, (int, float, bool, type(None))):
                return value
            elif isinstance(value, ObjectId):
                return value
            else:
                return str(value)
        finally:
            self._sanitization_depth -= 1

    def _sanitize_dict(self, doc: Dict[str, Any]) -> Dict[str, Any]:
        """Sanitize a dictionary, removing blocked operators."""
        result = {}
        for key, val in doc.items():
            if key.startswith('$'):
                if key in self.BLOCKED_OPERATORS:
                    continue
                if self._strict and key not in self.ALLOWED_OPERATORS:
                    continue
                result[key] = self.sanitize_value(val)
            else:
                result[key] = self.sanitize_value(val)
        return result


class ConnectionPool:
    """Manages MongoDB connection lifecycle."""

    def __init__(self, uri: str, db_name: str):
        self._client = MongoClient(uri, serverSelectionTimeoutMS=5000)
        self._db = self._client[db_name]
        self._lock = threading.RLock()
        self._shutting_down = False
        self._active_queries = 0

    @property
    def db(self):
        return self._db

    def acquire(self):
        with self._lock:
            if self._shutting_down:
                raise RuntimeError("Connection pool is shutting down")
            self._active_queries += 1

    def release(self):
        with self._lock:
            self._active_queries -= 1

    def shutdown(self, timeout: float = 5.0):
        with self._lock:
            self._shutting_down = True

        deadline = time.time() + timeout
        while time.time() < deadline:
            with self._lock:
                if self._active_queries == 0:
                    break
            time.sleep(0.1)

        self._client.close()


class QueryBuilder:
    """Builds safe MongoDB queries from user input."""

    def __init__(self, serializer: QuerySerializer):
        self._serializer = serializer
        self._query_cache: Dict[str, Dict] = {}

    def build_filter(self, field: str, condition: Any, use_cache: bool = True) -> Dict:
        """Build a filter document for a single field condition."""
        cache_key = self._compute_cache_key(field, condition)

        if use_cache and cache_key in self._query_cache:
            return self._query_cache[cache_key]

        if isinstance(condition, dict):
            sanitized = self._serializer.sanitize_value(condition)
            filter_doc = {field: sanitized}
        else:
            filter_doc = {field: {'$eq': condition}}

        if use_cache:
            self._query_cache[cache_key] = filter_doc

        return filter_doc

    def build_compound_filter(self, filters: Dict[str, Any]) -> Dict:
        """Build a compound filter from multiple field conditions."""
        compound = {}
        for field, condition in filters.items():
            partial = self.build_filter(field, condition, use_cache=False)
            compound.update(partial)
        return compound

    def _compute_cache_key(self, field: str, condition: Any) -> str:
        raw = f"{field}:{repr(condition)}"
        return hashlib.sha256(raw.encode()).hexdigest()[:16]


class UserRepository:
    """Repository for user document operations."""

    # PBKDF2 parameters for password hashing.
    _PBKDF2_ITERATIONS = 200_000
    _PBKDF2_ALGORITHM = 'sha256'

    def __init__(self, pool: ConnectionPool, query_builder: QueryBuilder, password_salt: bytes):
        self._pool = pool
        self._qb = query_builder
        self._collection_name = 'users'
        self._password_salt = password_salt

    def find_users(self, search_params: Dict[str, Any]) -> List[Dict]:
        """Find users matching the given search parameters."""
        self._pool.acquire()
        try:
            filter_doc = self._qb.build_compound_filter(search_params)
            collection = self._pool.db[self._collection_name]
            cursor = collection.find(filter_doc, {'password_hash': 0})
            return list(cursor.limit(100))
        finally:
            self._pool.release()

    def find_by_username(self, username: str) -> Optional[Dict]:
        """Find a single user by exact username match."""
        self._pool.acquire()
        try:
            filter_doc = self._qb.build_filter('username', username)
            collection = self._pool.db[self._collection_name]
            return collection.find_one(filter_doc, {'password_hash': 0})
        finally:
            self._pool.release()

    def authenticate(self, username: str, password: str) -> Optional[Dict]:
        """Authenticate a user with username and password."""
        self._pool.acquire()
        try:
            filter_doc = self._build_auth_filter(username, password)
            collection = self._pool.db[self._collection_name]
            user = collection.find_one(filter_doc)
            if user:
                return {k: v for k, v in user.items() if k != 'password_hash'}
            return None
        finally:
            self._pool.release()

    def _hash_password(self, password: str) -> str:
        """Derive a slow, salted password hash using PBKDF2-HMAC-SHA256."""
        derived = hashlib.pbkdf2_hmac(
            self._PBKDF2_ALGORITHM,
            password.encode(),
            self._password_salt,
            self._PBKDF2_ITERATIONS,
        )
        return derived.hex()

    def _build_auth_filter(self, username: str, password: str) -> Dict:
        """Build authentication filter - uses direct match for performance."""
        # Password is verified via a slow, salted PBKDF2 hash comparison
        # Username filter uses the query builder for consistency
        pw_hash = self._hash_password(password)
        username_filter = self._qb.build_filter('username', str(username))
        # Merge with password hash check
        username_filter['password_hash'] = pw_hash
        return username_filter


class Application:
    """Main application with graceful shutdown."""

    def __init__(self, mongo_uri: str, db_name: str):
        self._pool = ConnectionPool(mongo_uri, db_name)
        serializer = QuerySerializer(strict_mode=True)
        qb = QueryBuilder(serializer)
        password_salt = self._load_password_salt()
        self.user_repo = UserRepository(self._pool, qb, password_salt)
        self._setup_signal_handlers()

    @staticmethod
    def _load_password_salt() -> bytes:
        """Load the application password salt from the environment.

        A stable per-deployment salt is required so that hashes remain
        verifiable across restarts. It must be provided out-of-band.
        """
        salt_hex = os.environ.get('PASSWORD_SALT')
        if not salt_hex:
            raise RuntimeError(
                "PASSWORD_SALT environment variable must be set to a hex-encoded salt"
            )
        return bytes.fromhex(salt_hex)

    def _setup_signal_handlers(self):
        signal.signal(signal.SIGTERM, self._handle_shutdown)
        signal.signal(signal.SIGINT, self._handle_shutdown)

    def _handle_shutdown(self, signum, frame):
        print(f"Received signal {signum}, initiating graceful shutdown...")
        self._pool.shutdown(timeout=10.0)
        sys.exit(0)

    def handle_search_request(self, params: Dict[str, Any]) -> List[Dict]:
        """Handle an incoming search request."""
        allowed_fields = {'username', 'email', 'role', 'status', 'created_after'}
        filtered_params = {k: v for k, v in params.items() if k in allowed_fields}

        if 'created_after' in filtered_params:
            filtered_params['created_at'] = {'$gte': filtered_params.pop('created_after')}

        return self.user_repo.find_users(filtered_params)

    def handle_login_request(self, credentials: Dict[str, str]) -> Optional[Dict]:
        """Handle a login request."""
        username = credentials.get('username', '')
        password = credentials.get('password', '')

        if not username or not password:
            return None

        if not isinstance(username, str) or not isinstance(password, str):
            return None

        return self.user_repo.authenticate(username, password)
